UPDATE companies SET description='Crego Metal Systems, operating as Crego Roofing of New Mexico, has been based in the North Valley of Albuquerque (Los Ranchos de Albuquerque) since its founding in 1980. The company is family-owned and operated, with Stephen and Brenda Gregg serving as primary contacts. It began as a local installer and manufacturer of metal roofing for both residential and commercial projects.

The firm fabricates cut-to-length metal roof panels, flashing, and trim on-site using UL-approved roll-forming lines. Its product range includes CMS, R-Panel, and standing-seam profiles, along with seamless and box gutters, plaster trims, and custom plasma-cut silhouettes. Most standard orders are ready for same-day pickup; larger orders typically ship within three days. The facility also produces custom copper designs and offers green roofing solutions.

Its panels and flashing have been tested to ANSI/SPRI/ES-1 standards, exceeding minimum wind-uplift requirements. Past projects span single-family homes, commercial buildings, and specialty installations requiring custom metalwork.

The company emphasizes its “Edge of Quality Roofing” standard, combining UL-certified manufacturing with a price-match guarantee. Family ownership and local production allow quick turnaround and direct communication with the fabrication team.', certifications=ARRAY['UL approved (roof panel machine lines)']::text[], profile='{"capabilities": ["Cut-to-length metal roof panel fabrication", "Roof flashing fabrication", "Custom metal fabrication", "Plasma cutting", "Gutter fabrication (seamless, box, K-style)", "Trim fabrication (lath & plaster trim, J-weep, Z-flashing, plaster stop)", "Custom copper design", "Metal roof installation", "Green roofing solutions"], "industries": ["Residential construction", "Commercial construction", "Roofing", "Green building"], "materials": ["Galvalume", "Copper"], "equipment": ["UL approved roof panel machine lines"], "volume": "", "lead_time": "Same-day pickup for standard orders; 3 days or less for larger orders", "tolerances": "", "built_on": ["UL-approved roof panel machine lines", "ANSI/SPRI/ES-1 tested flashing exceeding wind-uplift standards", "Same-day pickup for most orders", "Family-owned and operated since 1980", "Price-match guarantee"], "facts_used": ["Founded 1980 -> db", "Family-owned and operated since 1980 -> /", "Location: Albuquerque, NM (Los Ranchos de Albuquerque) -> /", "Manufactures residential and commercial metal roof panels, flashing, trim, gutters -> /", "UL approved roof panel machine lines -> /about", "ANSI/SPRI/ES-1 tested metal flashing exceeding wind uplift standards -> /about", "Same-day pickup for most orders, larger orders 3 days or less -> /about", "Plasma cutting services -> /", "Custom copper design -> /about", "Green solutions -> /about", "Price matching guarantee -> /", "Contacts: Stephen Gregg, Brenda Gregg -> /about", "Business License #401273, CRS# 03-516317-008 -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We are a local installer and leading manufacturer of residential and commercial metal roofs since 1980", "founded_year": "1980", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='crego-metal-systems' AND approved AND profile IS NULL;
UPDATE companies SET description='Crittco Cable & Fiber is based in Jonesboro, Arkansas. The company traces its roots to 2002 when Matt Hale, a 20-year veteran of the water and sewer industry, partnered with Barry Brawner, who brought 30 years of telecommunications experience. They formed the business as a subsidiary of Crittco Construction and incorporated it in May 2007.

The firm operates as a full-service utility contractor with a focus on directional drilling. From an 8,000-square-foot shop supplemented by storage units and a covered wash bay, a crew of 12 to 30 runs a fleet that includes six drill rigs (ranging from a 7×11 to a 24×40), bucket trucks, backhoes, mini excavators, plows, vacuum excavators, bulldozers, and specialized equipment for duct washing and fiber blowing. Services span directional drilling, copper and fiber splicing, plowing, pulling and tugging, trenching and excavating, utility locating, aerial placement, duct washing, fiber blowing, and sewer, water, drainage, and electric installation.

Crittco serves telecommunications carriers such as Ritter Communications and AT&T, municipal utilities including City Water and Light in Jonesboro, and commercial contractors on projects for Hino Motors in Marion, Sam’s Wholesale in Jonesboro, Greene County Tech School in Paragould, and Home Depot in Jonesboro. The company also performed cable, fiber, and electric installation around new runways at Memphis International Airport.

The founders built the business on a reputation for high-quality work, on-time performance, and diversified project experience. Current leadership emphasizes evolving technology, quality workmanship, customer-oriented relationships, and a safe, efficient, environmentally friendly approach. The company describes its workforce as a family, with many employees remaining since the early years.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Directional drilling", "Cable splicing (copper and fiber optic)", "Plowing", "Pulling and tugging", "Trenching and excavating", "Utility locating", "Aerial fiber and copper placement", "Duct washing", "Fiber blowing", "Sewer, water, drainage, and electric installation", "Communication site work"], "industries": ["Telecommunications", "Municipal utilities", "Commercial construction", "Airport infrastructure"], "materials": ["Copper cable", "Fiber optic cable (single and ribbon)", "HDPE pipe", "Steel pipe", "Poly pipe", "Innerduct", "Microfiber"], "equipment": ["Six drill rigs (7\u00d711 to 24\u00d740)", "Boring rigs", "Bucket trucks", "Backhoes", "Mini excavators", "Cable plows", "Vacuum excavators", "Bulldozers", "Service trucks", "Low boys", "Tuggers", "Reel trailers", "Dump trucks", "Duct washing machine", "Trench boxes", "Rock tubs", "Blowers", "Confined space equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["High-quality work and on-time performance", "Diversified project experience across telecom, utility, and commercial construction", "Fleet of six directional drill rigs (7\u00d711 to 24\u00d740)", "Commitment to evolving technology and environmentally friendly practices", "Family-oriented culture with long-tenured employees"], "facts_used": ["Founded 2002 by Matt Hale and Barry Brawner -> /about", "Incorporated May 2007 as subsidiary of Crittco Construction -> /about", "Hale 20 years water/sewer, Brawner 30 years telecom -> /about", "Headquarters Jonesboro, Arkansas -> db, /", "Licensed 