UPDATE companies SET description='Colorado Springs Sawmill at Penrose operates from 240 3rd Street in Penrose, Colorado.

Core processes include urban milling of local logs, kiln drying using a Nyle System high-performance dry kiln that cuts drying time dramatically, and wood-and-metal fabrication. The shop also sells imported live-edge slabs and offers kiln-drying services to other woodworkers.

The company''s arborist division, A Noble Tree Company, provides ISA-certified tree care — including technical crane removals and pruning — across the Colorado Springs area.

The operation distinguishes itself by offering a full chain from tree removal through kiln-dried lumber to finished furniture, all sourced locally. The Nyle kiln reduces wait times for furniture-grade slabs, while the ISA-certified arborist crew ensures professional tree care.', certifications=ARRAY['ISA Certified Arborist']::text[], profile='{"capabilities": ["Custom furniture design", "Timber art", "Fireplace mantel fabrication", "Urban milling", "Kiln drying (Nyle System)", "Arborist services", "Forestry services", "Live-edge slab sales", "Wood and metal fabrication"], "industries": [], "materials": ["Wood (urban-sourced)", "Metal", "Imported live-edge slabs"], "equipment": ["Nyle System high-performance dry kiln"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Nyle System kiln cuts drying time for furniture-grade slabs", "Urban milling converts dead neighborhood trees into lumber", "ISA Certified Arborist crew with 14 years'' experience", "Custom furniture built from clients'' own trees", "Locally owned and operated in Penrose, CO"], "facts_used": ["Location: 240 3rd Street, Penrose, CO 81240 -> /", "Craftsman Mitch mentioned in testimonials -> /", "Motto: ''from disaster to design'' -> /", "Services: custom furniture design, urban milling, kiln for hire, arborist services, forestry services -> /services", "Nyle System high-performance dry kiln -> /services", "ISA Certified Arborist, 14 years experience, locally owned and operated (A Noble Tree Company) -> /services", "Custom furniture, mantels, benches, chairs, tables -> /services, /", "Imported live-edge slabs -> /", "Wood and metal fabrication -> /services", "Delivery offered -> /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Here at Colorado Springs Sawmill at Penrose, we create the custom furniture of your dreams.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='custom-woodworking-colorado-springs-sawmill-at-penrose-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Custom Works Inc. operates from Naperville, Illinois, where Serbian‑Macedonian founders Stefan and Melanie launched the business to blend Balkan woodworking heritage with Chicago‑area home remodeling. Stefan grew up in a small southern Serbian town learning carpentry alongside his grandfather, Dedo Stojan, while Melanie brought project‑management and interior‑design expertise. Together they built a husband‑and‑wife team focused on custom woodwork and full‑home renovations.

The shop delivers full‑service remodeling backed by in‑house woodworking: kitchens, bathrooms, staircases, mudrooms, built‑ins, vanities, custom furniture, and outdoor structures such as decks and patios. Projects follow a four‑step process — consultation, design, fabrication (typically 8‑10 weeks), and installation — with the team handling everything from flooring and fireplace updates to media walls and basement rebuilds.

Customers are residential owners across the Chicagoland suburbs. The firm also tackles smaller jobs such as pantry shelving and bay‑window benches.

Custom Works positions itself against “fast furniture” by emphasizing pieces meant to last generations. The founders cite European‑rooted values — tradition, quality, integrity, sustainability — and pledge ethically sourced lumber. Clients repeatedly note transparent communication, realistic timelines, and a willingness to incorporate personal materials into one‑of‑a‑kind pieces.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Full home remodeling", "Custom woodworking", "Carpentry", "Custom furniture design and fabrication", "Cabinetry (kitchen, bathroom, built-ins)", "Vanity fabrication", "Staircase construction and remodeling", "Mudroom design and build", "Outdoor construction (decks, patios)", "Hardwood flooring installation", "Custom built-ins and shelving", "Fireplace surround updates", "Wall paneling and media walls", "Basement remodeling", "Design consultation", "Project management", "Installation services"], "industries": ["Residential home remodeling", "Custom woodworking", "Carpentry", "Cabinetry", "Outdoor construction"], "materials": ["Wood (ethically and responsibly sourced)"], "equipment": [], "volume": "", "lead_time": "8-10 weeks for fabrication and delivery", "tolerances": "", "built_on": ["Furniture built to last generations, not replaced yearly", "Ethically and responsibly sourced wood and materials", "European craftsmanship values: tradition, quality, integrity, sustainability", "Transparent communication and realistic project timelines", "Custom designs incorporating client\u2019s own materials (e.g., family tree lumber)"], "facts_used": ["Naperville, Illinois headquarters -> db", "Founders Stefan (CEO) and Melanie (Co-founder) -> /about", "Stefan''s carpentry background with grandfather in Serbia -> /about", "Melanie''s project management and interior design background -> /about", "Full home remodeling services with custom woodworking -> /", "Services: kitchens, bathrooms, staircases, mudrooms, built-ins, vanities, custom furniture, outdoor construction -> /", "Four-step process: consultation, design, fabrication (8-10 weeks), installation -> /", "Ethically and responsibly sourced wood and materials -> /about", "Values: tradition, quality, integrity, sustainability (European way) -> /about", "Residential clients in Chicagoland suburbs -> /", "Example projects: basement remodel with bar/media wall, coffee table from client''s tree, mudroom, hardwood flooring, staircase, entertainment wall, pantry shelving, bay-window bench -> /", "Position against fast furniture; pieces made to last generations -> /about", "Transparent communication and realistic timelines -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Custom-designed furniture and cabinetry built specifically for your home. Dining tables, built-ins, vanities, and one-of-a-kind woodwork shaped by the natural grain and designed for everyday living.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='custom-works-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Cut & Dry Lumber Company operates in Albuquerque, New Mexico, where it launched an urban sawmill in 2018. The business is family-owned, building on more than 40 years of experience in the local tree-service industry.

The company produces live-edge slabs, custom-milled lumber, and made-to-order furnishings such as river tables, bar tops, benches, and desks. Its shop runs a Wood-Mizer LX 250 band mill capable of 54-inch-wide by 18-foot-long cuts, supplemented by a 24-inch planer, a 16-inch jointer, and a large sander for surfacing.

Customers include interior designers seeking custom furnishings, woodworkers and DIYers buying raw slabs, and clients needing contract shop work for milling or finishing.

The stated mission is to reduce green waste by giving a second life to Albuquerque’s trees and to build a tree-recycling culture in New Mexico. The owners frame the sawmill as a way to preserve the story of the urban forest in homes, shops, and gathering spaces.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Live-edge slab production", "Custom milling", "Planing", "Jointer work", "Sanding", "Finishing", "Custom furniture fabrication", "Epoxy river table fabrication", "Contract milling", "Log harvesting and processing"], "industries": ["Interior design", "Woodworking", "DIY/home improvement", "Custom furniture", "Contract manufacturing"], "materials": ["Ash", "Cottonwood", "Cypress", "Elm", "Honey Locust", "Juniper", "Maple", "Mulberry", "Pine", "Poplar", "Russian Olive", "Sycamore"], "equipment": ["Wood-Mizer LX 250 band mill", "Industrial 24-inch planer", "16-inch jointer", "Large sander"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% sourced and crafted in Albuquerque", "Urban-forest upcycling: only trees removed for instability, disease, or age", "Wood-Mizer LX 250 band mill (54\" x 18\") with in-house planer, jointer, and sander", "Air-drying cycle up to 2 years adapted to desert climate", "No kiln-dried, treated, or structural lumber carried"], "facts_used": ["Founded 2018 -> /about", "Family-owned -> /about", "40+ years in tree service -> /about", "Urban sawmill started 2018 -> /about", "Partnered with Baca''s Trees -> /", "Live-edge slabs, custom milling, furnishings -> /services", "Wood-Mizer LX 250 band mill (54\" x 18\") -> /services", "Industrial 24\" planer, 16\" jointer, large sander -> /services", "Wood species list -> /services", "Air-drying up to 2 years -> /services", "No kiln-dried, treated, or structural lumber -> /services", "Pricing $5-22 per board foot -> /services", "Customers: interior designers, DIYers, woodworkers -> /", "Contract shop work mentioned -> /", "Mission: reduce green waste, build tree-recyc