UPDATE companies SET description='East Jordan Plastics operates from East Jordan, Michigan, where it was founded four generations ago by Ken and Shirley Diller as East Jordan Box and Crate Co. The business began by producing wooden greenhouse flats for bedding plant growers in the Midwest and has remained in the family ever since.

Today the company manufactures a comprehensive line of sustainable plastic plant containers for greenhouses and nurseries. Its injection-molded product families include the SHUTTLE™ series of pots, hanging baskets, planters and bowls; the patented SHUTTLE POT® STADIUM® line of grower pots and trays with offset-printable flat sides; and a range of trays, carriers, flats, inserts, and plug and propagation trays precision-engineered for automated destacking, filling, transplanting and transport equipment. A closed-loop recycling program, certified for Post-Consumer Recycled (PCR) plastic by AM Testing, feeds reclaimed material back into production.

The company serves only the horticultural market—greenhouse growers, nursery operators, bedding plant producers and retail garden centers.

East Jordan Plastics says its differentiation rests on four pillars: a closed-loop recycling system with third-party PCR certification, product designs tailored for high-speed automation, precision tooling that holds exact tolerances for plug trays, and a family-owned structure that has kept the focus on horticulture for nearly 80 years.', certifications=ARRAY['Post-Consumer Recycled (PCR) Plastic Certification from AM Testing']::text[], profile='{"capabilities": ["Injection molding", "Closed-loop recycling", "Precision engineering for plug and propagation trays", "Custom offset printing on containers", "Label application compatibility", "Design for automated destacking, filling, transplanting, and transport equipment", "Manufacturing of plastic plant containers (pots, hanging baskets, planters, bowls, trays, carriers, flats, inserts)"], "industries": ["Horticulture", "Greenhouse growing", "Nursery", "Bedding plant production", "Retail horticulture"], "materials": ["Post-Consumer Recycled (PCR) Plastic", "Plastic"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Closed-loop recycling program with Post-Consumer Recycled (PCR) Plastic Certification from AM Testing", "Products designed for automated destacking, filling, transplanting and transport equipment", "Precision-engineered plug and propagation trays held to exact tolerances", "Patented SHUTTLE POT\u00ae STADIUM\u00ae line with offset-printable flat sides for custom graphics", "Family-owned and operated for four generations"], "facts_used": ["Founded by Ken and Shirley Diller as East Jordan Box and Crate Co. -> db", "Headquarters in East Jordan, Michigan -> db", "Family-owned and operated -> / (testimonial)", "Manufactures injection-molded plastic plant containers -> /", "Closed-loop recycling with PCR certification from AM Testing -> /", "Serves horticulture industry (greenhouses, nurseries, bedding plant growers) -> /", "Products designed for automated destacking, filling, transplanting, transport equipment -> /", "Precision-engineered plug and propagation trays to exact tolerances -> /", "Patented SHUTTLE POT\u00ae STADIUM\u00ae line with offset print capability -> /", "Customer testimonials from Bradford Greenhouses and Linwell Gardens -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "injection-molded SHUTTLE\u2122 line", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='east-jordan-plastics' AND approved AND profile IS NULL;
UPDATE companies SET description='Ebanista School of Fine Woodworking operates in the Georgetown neighborhood of Seattle, Washington. The school launched its first classes in the fall of 2018, established in response to long-standing demand for a high-caliber woodworking institution in the Pacific Northwest.

The school provides instruction in furniture design and construction, led by instructors who each bring at least 45 years of professional woodworking experience. The facility houses both classrooms and a professional furniture studio, and class sizes are deliberately kept small to maximize individual attention. Curriculum covers foundational skills that enable graduates to pursue cabinetmaking, instrument making, boatbuilding, fine carpentry, and other precision woodworking disciplines.

Programs serve students of all ages seeking to become designers and makers, with the training applicable across cabinetmaking, instrument making, boatbuilding, and fine carpentry sectors. The school positions itself as a gateway for those entering professional woodworking trades or related design fields.

Ebanista was created to fill a gap in the region for advanced woodworking education, answering repeated requests for a school of this caliber. The name, Spanish for "fine woodworker," reflects a philosophy that wood''s variability makes it a uniquely expressive material, a perspective shared by director Jonathan Cohen in a 2016 Google talk.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Furniture design instruction", "Fine woodworking instruction", "Cabinetmaking training", "Instrument making training", "Boatbuilding training", "Fine carpentry training"], "industries": ["Education", "Woodworking", "Furniture Design", "Cabinetmaking", "Instrument Making", "Boatbuilding", "Fine Carpentry"], "materials": ["Wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Instructors with minimum 45 years professional woodworking experience", "Intentionally limited class sizes for maximum student attention", "Combined school and professional furniture studio facility", "Curriculum designed as foundation for diverse woodworking disciplines", "Founded in response to sustained demand for high-level woodworking education in the Pacific Northwest"], "facts_used": ["Located in Georgetown area of Seattle -> /", "Classes began in fall 2018 -> /", "Instructors have minimum 45 years experience as professional woodworkers -> /", "Facility houses both a school and a professional furniture studio -> /", "Class sizes intentionally limited -> /", "Training applicable to cabinetmaking, instrument making, boatbuilding, fine carpentry -> /", "Founded in response to requests for a school of this caliber -> /", "Ebanista means ''fine woodworker'' in Spanish -> /", "Director Jonathan Cohen quoted from 2016 Google talk -> /"], "company_type": "Other", "makes_products": "yes", "type_evidence": "It is fully equipped and houses both a school and a professional furniture studio.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "ex