UPDATE companies SET description='Edge Core Tech (ECT) operates from Reno, Nevada.

ECT provides sheet metal fabrication services including laser cutting, numerically controlled full-sheet punching, automated bending and forming, robotic and manual welding (AWS certified), spot welding, assembly, and finishing. The shop also runs CNC milling on a HAAS VF-4SS and hardware insertion with a HAEGER press, supported by engineering and programming staff that can take a project from concept through finished part. The company notes it offers thousands of combinations of sheet metal materials, finishes, tolerances, markings, and certifications per order.

The company serves customers who need custom metal parts, from prototype through production, but does not list specific industry verticals or named clients in its public materials.

ECT emphasizes a hands-on approach: qualified engineers work from blueprints, sketches, samples, or digital files to turn concepts into physical reality, while OSHA-certified employees and a certified welding department underscore a focus on safety and weld quality. The firm also promotes cost-effective solutions and a global manufacturing network to give clients peace of mind.', certifications=ARRAY['AWS welding certification','OSHA employee certification']::text[], profile='{"capabilities": ["Laser cutting", "NC full sheet punching", "Automated bending and forming", "Robotic welding", "Manual welding", "AWS certified welding", "Spot welding", "Assembly", "Finishing", "CNC milling", "Hardware pressing", "Engineering and programming", "Design assistance"], "industries": [], "materials": [], "equipment": ["HAAS VF-4SS CNC mill", "HAEGER hardware press"], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Company name Edge Core Tech (ECT) -> db", "Headquarters Reno, Nevada -> db", "Sheet metal fabrication capabilities: laser cutting, NC punching, automated bending/forming, robotic/manual welding, AWS certified welding, spot welding, assembly, finishing -> /", "Engineering and programming from design to finished part -> /", "CNC milling with HAAS VF-4SS -> /", "Hardware pressing with HAEGER press -> /", "Two generations of pride, excellence, customer commitment -> /", "OSHA certified employees -> /", "Thousands of combinations of materials, finishes, tolerances, markings, certifications -> /", "Qualified engineers work from blueprints, sketches, samples, digital files -> /", "Cost-effective solutions, global manufacturing network -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "At ECT our sheet metal fabrication capabilities include laser cutting, numerically controlled full sheet punching, automated bending and forming, robotic, and manual welding, AWS certified welding, spot-welding, assembly, and finishing.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='edge-core-tech' AND approved AND profile IS NULL;
UPDATE companies SET description='Ehmke Manufacturing Company, Inc. was founded in May 1929 by Howard Ehmke in Philadelphia, Pennsylvania. The company operates a 50,000-square-foot single-floor facility and holds HUBZone certification.

The firm engineers and fabricates technical fabric products including soft-sided cases, bags, tarpaulins, promotional cases, athletic and fitness bags, thermal and acoustic blankets for aircraft such as the Boeing CH-47 Chinook and V-22 Osprey, ground support covers, vehicular covers, field kitchen fabric components, MOLLE packs, medical cases, tactical gear, straps, and web assemblies. It has produced over 8,000 distinct products for the defense industry. Capabilities encompass engineering support, prototyping, LEAN manufacturing, computer-aided cutting, single- and double-needle sewing, box and bar tacking, fabric welding, grommet installation, and an operator cross-training program. The quality system is certified to ISO 9001:2015 and AS9100:2016, with additional MIL-I-45208 and statistical process control qualifications.

Customers include the U.S. Armed Forces, allied militaries, defense contractors, commercial OEMs (notably Boeing Integrated Defense Systems), and various industrial sectors. Specific programs served include thermal/acoustic blankets for rotorcraft and fabric components for the Mobile Kitchen Trailer.

Ehmke emphasizes a mission to be a custom, flexible, and reliable production resource. It differentiates itself as one of few textile manufacturers with dual ISO 9001 and AS9100 registration, and has recently developed a 22-item AI-driven improvement roadmap targeting scheduling, inventory visibility, proposal development, and operational decision-making.', certifications=ARRAY['ISO 9001:2015','AS9100:2016','MIL-I-45208','Statistical Process Control (US Government Certified)','IFAI Master Fabrics Craftsman Certification','IFAI Industrial Fabrics Manager Certification','IFAI Certified Project Planner Certification']::text[], profile='{"capabilities": ["Engineering support services", "Prototyping", "LEAN manufacturing", "Computer-aided cutting", "Single-needle sewing", "Double-needle sewing", "Box tacking", "Bar tacking", "Fabric welding", "Grommet installation", "Operator cross-training program", "Statistical process control", "Reverse engineering", "Cost-effective design modification", "AI-assisted inventory management", "AI-assisted proposal development", "Shop floor scheduling optimization"], "industries": ["Defense", "Aerospace", "Industrial", "Commercial OEM", "Government"], "materials": [], "equipment": ["Computer-aided cutting tables", "Commercial sewing machines", "Industrial sewing machines", "Paraloft sewing machines", "Military sewing machines", "Box and bar tackers", "Presses and punch machines", "Fabric welding machines", "Grommet machines"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["One of few textile manufacturers with ISO 9001:2015 and AS9100:2016 registration", "Produced over 8,000 distinct products for the defense industry", "50,000 sq ft facility with computer-aided cutting tables and LEAN flexible production lines", "AI-enhanced operations with a 22-use-case roadmap for scheduling, inventory, and proposals", "HUBZone-certified and registered in SAM for government contracting"], "facts_used": ["Founded 1929 -> /about-us", "Headquarters Philadelphia, PA -> /about-us", "50,000 sq ft facility -> /about-us", "HUBZone certification -> /about-us", "ISO 9001:2015 and AS9100:2016 certifications -> /about-us", "Produced over 8,000 products for defense -> /capabilities", "Thermal acoustic blankets for Boeing CH-47 and V-22 -> /about-us", "Mobile Kitchen Trailer fabric components -> /about-us", "Engineering support, prototyping, LEAN manufacturing -> /capabilities", "Computer-aided cutting tables, sewing machines, welding machines, grommet machines -> /capabilities", "AI-enhanced capabilities with 22 use cases -> /capabilities", "Registered in SAM for government contracting -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Since 1929, Ehmke Manufacturing Company, Inc. has engineered and fabricated a diverse range of technical fabric products for the U.S. Armed Forces, its allies, the defense industry, commercial OEMs and for a host of industrial applications.", "founded_year": "1929", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["Registered in System for Award Management (SAM)"], "languages": [], "social_links": [], "ownership_tags": ["HUBZone"]}'::jsonb, updated_at=now() WHERE slug='ehmke-manufacturing-co-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='EightTwenty was founded in 2020 by Tony Capucille in Oklahoma City, Oklahoma. The company began as a vertically integrated solar developer aimed at serving Middle America, starting operations in Oklahoma in 2021 due to the state''s high sunshine ranking but low solar adoption. Co-founder Kent Cissell joined as president, and the business is owned by employees and local investors in each market they serve.

The company designs and installs solar photovoltaic systems for residential, commercial, and tax-exempt customers, integrating battery storage and EV charging where needed. The firm describes itself as a vertically integrated developer managing the full project lifecycle from utility bill analysis to system commissioning.

EightTwenty serves homeowners looking to hedge against rising electricity costs, commercial property owners and landlords leveraging tax incentives, tax-exempt institutions such as non-profits eligible for direct-pay credits, and builder partners seeking to incorporate solar, storage, and EV charging into new projects.

The company says its differentiation lies in a culture built on respect, focus, and quality, with a goal of turning every customer into a "raving fan." Leadership emphasizes that employee ownership and local investors align the business with community outcomes, and the Give Solar program directs a portion of each sale to help neighbors access clean energy.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Solar PV system design", "Solar installation", "Energy storage integration", "EV charging integration", "Project development and permitting", "Engineering and design", "Give Solar community program"], "industries": ["Residential solar", "Commercial solar", "Non-profit/tax-exempt solar", "Builder/partner solar integration", "Solar energy development"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Vertically integrated solar developer serving Middle America", "In-house installation craftsmen", "Employee-owned with local investors in each market", "Customer experience focus turning clients into raving fans", "Expanded service across Oklahoma, Texas, Arkansas, Indiana, Kentucky"], "facts_used": ["Founded in 2020 by Tony Capucille -> db description", "Started in Oklahoma in 2021 -> /about-us page", "Co-founded by Kent Cissell -> /about-us page", "Employee-owned with local investors -> /about-us page", "Vertically integrated solar developer -> /about-us page", "In-house craftsmen install -> / homepage", "Services residential, commercial, tax-exempt, builder partners -> / homepage", "Expanded to Texas, Arkansas, Indiana, Kentucky -> /about-us page", "Give Solar program -> / homepage", "Culture of respect, focus, quality -> /about-us page", "Headquarters Oklahoma City, Oklahoma -> db hq_city/hq_state_label", "LinkedIn URL -> db linkedin_url"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Our in-house craftsman install and turn on your project, connecting you to the sun.", "founded_year": "2020", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/eighttwentyenergy/"], "ownership_tags": ["Employee-owned"]}'::jsonb, updated_at=now() WHERE slug='eighttwenty' AND approved AND profile IS NULL;
